#!/usr/bin/env bash
# privacy-tracking-20261115: add Email delivery and link tracking section to /privacy.
set -euo pipefail
W=/opt/trendi/releases/20261108-vps/website
F=$W/site/privacy.html
BASE=5e14ff93deb3a410787b9d2dd010cb044d8d7607bfa090325593636f95c3e58f
NEW=fa6d1c6aaf398359927bf92b017af7da41a3bad406fdce37775873d64a360265
BK=/opt/trendi/backups/privacy-tracking-20261115
cur=$(sha256sum "$F" | cut -d' ' -f1)
[ "$cur" = "$BASE" ] || { echo "REFUSE: live privacy.html is $cur, expected base $BASE"; exit 3; }
tmp=$(mktemp); echo '' | base64 -d > "$tmp"
[ "$(sha256sum "$tmp" | cut -d' ' -f1)" = "$NEW" ] || { echo "REFUSE: payload hash mismatch"; exit 4; }
mkdir -p "$BK"; cp -p "$F" "$BK/privacy.html.bak"
printf 'cat %s/privacy.html.bak > %s\n' "$BK" "$F" > "$BK/ROLLBACK"
cat "$tmp" > "$F"; rm -f "$tmp"
echo "written $(sha256sum "$F" | cut -d' ' -f1)"
sleep 2
if bash "$W/scripts/seo-gate.sh" > "$BK/gate.log" 2>&1; then
  tail -3 "$BK/gate.log"; echo "GATE PASS"
else
  tail -15 "$BK/gate.log"; cat "$BK/privacy.html.bak" > "$F"; echo "GATE FAIL: rolled back to $(sha256sum "$F" | cut -d' ' -f1)"; exit 5
fi
